head.script:
// column_P_hideThreshold_2 의 페어 파일
//  - 부모 화면이 adaptiveFrame="true" 인 tabControl Content 로 이 화면을 불러온 뒤 createTarget() 을 호출한다.
//  - GridView 를 이 화면(Content Frame) 의 scope 에서 생성해야 GridView 의 상위 Frame 이 adaptiveFrame Content 가 된다.
scwin.onpageload = function () {
};



// 부모 화면이 만든 dataList / GridView 정의 문자열로 이 Frame 안에 target1 생성
scwin.createTarget = async function (strDlt, arrData, strTarget) {
    if (typeof target1 !== 'undefined' && target1) {
        target1.remove();
    }
    if (typeof dlt_bind !== 'undefined' && dlt_bind) {
        $p.data.remove("dlt_bind");
    }
    $p.data.create(strDlt);
    dlt_bind.setJSON(arrData, false);
    scwin.target1 = await $p.dynamicCreate("target1", "gridView", strTarget, grp_frame);
    return scwin.target1;
};
